    println!("zoxide {}\nAjeet D'Souza <98ajeet@gmail.com>\nhttps://github.com/ajeetdsouza/zoxide\n\nA smarter cd command for your terminal\n\nUsage:\n  zoxide <COMMAND>\n\nCommands:\n  add     Add a new directory or increment its rank\n  edit    Edit the database\n  import  Import entries from another application\n  init    Generate shell configuration\n  query   Search for a directory in the database\n  remove  Remove a directory from the database\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version\n\nEnvironment variables:\n  _ZO_DATA_DIR          Path for zoxide data files\n  _ZO_ECHO              Print the matched directory before navigating to it when set to 1\n  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded\n  _ZO_FZF_OPTS          Custom flags to pass to fzf\n  _ZO_MAXAGE            Maximum total age after which entries start getting deleted\n  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths\n");
}

fn get_data_dir() -> PathBuf {
    if let Ok(data_dir) = env::var("_ZO_DATA_DIR") {
        return PathBuf::from(data_dir);
    }

    #[cfg(target_os = "macos")]
    {
        if let Ok(home) = env::var("HOME") {
            return PathBuf::from(home).join(".local/share/zoxide");
        }
    }

    #[cfg(target_os = "windows")]
    {
        if let Ok(programdata) = env::var("PROGRAMDATA") {
            return PathBuf::from(programdata).join("zoxide");
        }
    }

    #[cfg(target_os = "linux")]
    {
        if let Ok(xdg_data_dir) = env::var("XDG_DATA_HOME") {
            return PathBuf::from(xdg_data_dir).join("zoxide");
        } else if let Ok(home) = env::var("HOME") {
            return PathBuf::from(home).join(".local/share/zoxide");
        }
    }

    PathBuf::from(".")
}

