+                            except ValueError:
+                                pass
+    elif source == "z":
+        db_path = os.path.join(path, "db")
+        if os.path.exists(db_path):
+            with open(db_path, 'r') as f:
+                for line in f:
+                    line = line.strip()
+                    if line and not line.startswith('#'):
+                        parts = line.split()
+                        if len(parts) >= 2:
+                            try:
+                                score = float(parts[1])
+                                add_entry(parts[0], score)
